<!-- This file is generated by AI. -->

<!--
  场景浏览器: 列出 `game/scene` 下的文件, 点击打开为场景卡。

  直接坐在通用 `FileTree` 上 —— 分页、搜索、展平、定位、拖放、右键全部复用, 这里只补
  场景专属的部分: 根目录、文件过滤、以及"新建/重命名/删除/暂存"这几项。

  ⚠️ 不带 `<style>` 块: 类名全部来自全局 `styles.css`, 加作用域哈希会让它们失配。
-->

<script lang="ts">
  import { gitStage } from '../commands/git';
  import { requestAlert } from '../confirm';
  import {
    copyRelativePathToClipboard,
    copySourcesToDirectory,
    createFile,
    createFolder,
    deletePath,
    ensureExtension,
    importFilesToDir,
    renamePath,
    validateName,
  } from '../fileops';
  import { refreshGitStatus } from '../git/status';
  import { buildDiagnosticIndex } from '../diagnostics/model';
  import { fs } from '../lib/fs';
  import { absToRel, buildGitLetterIndex, normalizeRelPath, stageMenuItem } from '../git/util';
  import { browserRelativePath, joinPath } from '../lib/paths';
  import { revealItemInDir } from '@tauri-apps/plugin-opener';
  import { openFile } from '../project';
  import { activeTabOf } from '../state/selectors';
  import { appStore } from '../state/store.svelte';
  import ContextMenu, { type ContextMenuItem } from './ContextMenu.svelte';
  import FileBadges from './FileBadges.svelte';
  import FileTree, { type FileNode, type FileTreeRevealRequest, type FileTreeViewStateCache } from './FileTree.svelte';
  import NameInputDialog from './NameInputDialog.svelte';

  let {
    viewStateCache,
    viewStateKey,
    revealRequest = null,
    onRevealComplete,
  }: {
    viewStateCache?: FileTreeViewStateCache;
    viewStateKey?: string;
    revealRequest?: FileTreeRevealRequest | null;
    onRevealComplete?: (id: number) => void;
  } = $props();

  const projectPath = $derived(appStore.projectPath);
  const sceneRoot = $derived(projectPath ? joinPath(projectPath, 'game', 'scene') : '');

  let refreshKey = $state(0);
  /** 空白处右键的位置 (菜单作用于当前目录) */
  let blankMenu = $state<{ x: number; y: number; dir: string } | null>(null);
  /** 条目右键的位置 (菜单作用于该条目) */
  let itemMenu = $state<{ x: number; y: number; node: FileNode } | null>(null);
  let prompt = $state<{ mode: 'file' | 'folder' | 'rename'; dir: string; node?: FileNode } | null>(null);

  const activeTab = $derived(activeTabOf(appStore));
  const selectedPath = $derived(activeTab?.kind === 'scene' ? activeTab.path : null);

  /*
   * 本组件自己发起的一次"定位" (导入后选中新文件)。
   *
   * 复用 `FileTree` 的 reveal 链路 —— 切目录、扩页、滚动与高亮都在那里, 自己再实现一套必然
   * 与"从选项卡栏定位过来"的行为分叉。**id 取负数**: 父级的请求是正数, 回调只拿到 id, 靠符号
   * 区分才不会把对方的请求清掉。
   */
  let localReveal = $state<FileTreeRevealRequest | null>(null);
  let localRevealSequence = 0;
  const effectiveReveal = $derived(localReveal ?? revealRequest);

  function revealImported(path: string): void {
    localRevealSequence += 1;
    localReveal = { id: -localRevealSequence, path };
  }

  function handleRevealComplete(id: number): void {
    if (localReveal?.id === id) {
      localReveal = null;
      return;
    }
    onRevealComplete?.(id);
  }

  function refresh(): void {
    refreshKey += 1;
  }

  /** 「添加资源」= 导入已有文件; 复制完刷新目录并定位到第一个 (与拖入的表现一致)。 */
  async function addResources(dir: string): Promise<void> {
    try {
      const created = await importFilesToDir(dir);
      if (created.length === 0) return;
      refresh();
      if (created[0]) revealImported(created[0]);
    } catch (error) {
      requestAlert('添加资源失败', String(error));
    }
  }

  /** 「复制相对路径」: 相对项目根, 口径在 `lib/paths.ts` (菜单 / 剪贴板 / 拖进编辑器共用)。 */
  async function copyRelativePath(path: string): Promise<void> {
    const project = projectPath;
    if (!project) return;
    await copyRelativePathToClipboard(project, path);
  }

  async function openScene(path: string): Promise<void> {
    try {
      await openFile(path);
    } catch (error) {
      console.error('打开场景失败', error);
    }
  }

  /**
   * 系统文件拖进来 = 与「添加资源」**同一套逻辑**: 拷贝进目标目录 (重名自动改名), 然后刷新。
   *
   * 路径由 `dnd/external-drop.svelte.ts` 经 webview 的拖放事件给出 (页面收不到系统的 `drop`,
   * 那里有完整说明)。目标目录可能是目录行 (拖到子目录上), 由 `FileTree` 判定;
   * 导入后定位到那一项 —— 拖进子目录时会自动打开那一层目录。
   */
  async function handleDropPaths(directory: string, paths: string[]): Promise<void> {
    if (paths.length === 0) return;
    try {
      const created = await copySourcesToDirectory(paths, directory);
      refresh();
      // 多个文件时只定位第一个: 用户的目光只需要一个落点
      if (created[0]) revealImported(created[0]);
    } catch (error) {
      requestAlert('导入失败', `${String(error)}\n\n目标目录：${directory}`);
    }
  }

  /**
   * 移入系统回收站,**不弹确认框**。
   *
   * 动作本身可恢复 (回收站), 而编辑页里删文件是高频操作, 每次都确认只会训练出"盲点确定";
   * 菜单项的名字已经把这个后果说清楚了。开始界面里删**整个项目目录**仍然要确认 (范围大得多的
   * 不可逆动作)。失败必须报出来 —— 静默失败会让人以为已经删掉了。
   */
  function removeEntry(node: FileNode): void {
    void (async () => {
      try {
        await deletePath(node.path);
        refresh();
      } catch (error) {
        requestAlert('移入回收站失败', `${node.name}\n\n${String(error)}`);
      }
    })();
  }

  function askStage(node: FileNode): void {
    const path = projectPath;
    if (!path) return;
    void (async () => {
      try {
        await gitStage(path, [absToRel(path, node.path)]);
        await refreshGitStatus(path);
      } catch (error) {
        requestAlert('暂存失败', `${node.name}\n\n${String(error)}`);
      }
    })();
  }

  /*
   * 工具栏 ⋮ 与列表空白处共用同一份菜单, 都作用于当前目录: 新建场景 / 添加资源 /
   * 新建文件夹 / 在文件管理器中打开 —— 四项一个都不能少。
   */
  function toolbarMenu(directory: string): ContextMenuItem[] {
    return [
      {
        key: 'new-file',
        label: '新建场景',
        iconName: 'DocumentAdd',
        onClick: () => (prompt = { mode: 'file', dir: directory }),
      },
      {
        key: 'import-resource',
        label: '添加资源',
        iconName: 'DocumentAdd',
        onClick: () => void addResources(directory),
      },
      {
        key: 'new-folder',
        label: '新建文件夹',
        iconName: 'FolderAdd',
        onClick: () => (prompt = { mode: 'folder', dir: directory }),
      },
      {
        key: 'reveal',
        label: '在文件管理器中打开',
        iconName: 'OpenFolder',
        onClick: () => void revealItemInDir(directory),
      },
    ];
  }

  /** 空白处右键: 与工具栏菜单同一套 (空白处就是"对当前目录操作")。 */
  const blankItems = $derived<ContextMenuItem[]>(blankMenu ? toolbarMenu(blankMenu.dir) : []);

  /*
   * 行徽标的数据源: 建一次表、每行查一次 —— 与资源浏览同一套做法。
   * 理由见 `ui/FileBadges.svelte`: 让每行自己读 store 会变成"每行一个订阅 + 每行 O(M) 查找"。
   */
  const gitLetters = $derived(buildGitLetterIndex(appStore.gitStatus));
  const diagCounts = $derived(buildDiagnosticIndex(appStore.diagnostics));

  /** 「暂存」这一项的状态; 与资源浏览共用同一条规则 (见 `git/util.ts`) */
  const stageState = $derived(
    itemMenu && projectPath
      ? stageMenuItem(appStore.gitStatus, projectPath, itemMenu.node.path)
      : { visible: false, disabled: true }
  );

  /*
   * 行菜单: 文件与目录**同一套**, 没有"目录 → 在此新建场景文件"的分支; 「在文件管理器中打开」
   * 必须紧跟在「复制相对路径」之后。顺序是: 暂存 (可见时) / 分隔 / 复制相对路径 /
   * 在文件管理器中打开 / 分隔 / 重命名 / 移入回收站。
   *
   * 「暂存」的可见性由 `git/util.ts` 的 `stageMenuItem` 决定: 未跟踪不显示, 已暂存且无改动
   * 则显示但禁用。
   */
  const itemItems = $derived<ContextMenuItem[]>(
    itemMenu
      ? [
          ...(!itemMenu.node.isDirectory && stageState.visible
            ? [
                {
                  key: 'stage',
                  label: '暂存',
                  iconName: 'Add' as const,
                  disabled: stageState.disabled,
                  title: stageState.disabled ? '此场景已暂存' : undefined,
                  onClick: () => askStage(itemMenu!.node),
                },
                { key: 'separator-stage', separator: true as const },
              ]
            : []),
          {
            key: 'copy-relative',
            label: '复制相对路径',
            iconName: 'Copy',
            onClick: () => void copyRelativePath(itemMenu!.node.path),
          },
          {
            key: 'reveal',
            label: '在文件管理器中打开',
            iconName: 'OpenFolder',
            onClick: () => void revealItemInDir(itemMenu!.node.path),
          },
          { key: 'separator-manage', separator: true },
          {
            key: 'rename',
            label: '重命名',
            iconName: 'Rename',
            onClick: () => (prompt = { mode: 'rename', dir: itemMenu!.node.path, node: itemMenu!.node }),
          },
          {
            key: 'delete',
            label: '移入回收站',
            iconName: 'Delete',
            danger: true,
            onClick: () => removeEntry(itemMenu!.node),
          },
        ]
      : []
  );

  const promptTitle = $derived(
    prompt?.mode === 'rename' ? '重命名' : prompt?.mode === 'folder' ? '新建文件夹' : '新建场景文件'
  );
  const promptInitial = $derived(prompt?.mode === 'rename' && prompt.node ? prompt.node.name : '');

  /** 缺扩展名时补 `.txt`; 名字里已经带点就原样保留 (用户可以显式写别的后缀)。 */
  function targetName(raw: string): string {
    return ensureExtension(raw, 'txt');
  }

  /**
   * 就地校验: 名称合法性与重名。
   *
   * 分两步是因为**重名检查要问磁盘**:
   * * `validateName` 是纯字符串规则 (非法字符、`.`、`..`);
   * * 存在性检查必须排除"只把大小写改了一下"的情况 —— 那种在 Windows 上目标路径与源路径
   *   指向同一个文件, 报"已存在"会让用户以为改不了。
   */
  async function validateTarget(raw: string): Promise<string | null> {
    const current = prompt;
    if (!current) return null;

    const formatError = validateName(raw);
    if (formatError) return formatError;

    const isRename = current.mode === 'rename' && current.node;
    const name = current.mode === 'folder' && !isRename ? raw.trim() : targetName(raw);
    const target = `${(isRename ? current.node!.path.replace(/[\\/][^\\/]*$/, '') : current.dir).replace(/[\\/]+$/, '')}\\${name}`;

    if (isRename && target.replace(/\\/g, '/').toLowerCase() === current.node!.path.replace(/\\/g, '/').toLowerCase()) {
      return null;
    }
    const info = await fs.exists(target);
    return info.exists ? '这个名字已经被占用了' : null;
  }

  async function submitPrompt(name: string): Promise<string | null> {
    const current = prompt;
    if (!current) return null;

    const invalid = validateName(name);
    if (invalid) return invalid;

    try {
      if (current.mode === 'file') {
        const created = await createFile(current.dir, name, 'txt');
        refresh();
        // 新建之后直接打开: 用户的意图是"建一个场景然后写它", 不该再让他去列表里找一遍
        await openScene(created);
      } else if (current.mode === 'folder') {
        await createFolder(current.dir, name);
        refresh();
      } else if (current.node) {
        const parent = current.node.path.slice(0, current.node.path.length - current.node.name.length);
        await renamePath(current.node.path, `${parent}${targetName(name)}`);
        refresh();
      }
      return null;
    } catch (error) {
      return String(error);
    }
  }

  /** git 状态按"项目内相对路径"索引, 因此徽标要把它算出来。 */
  function badgeRel(node: FileNode): string {
    const root = projectPath;
    return root ? absToRel(root, node.path) : node.rel;
  }
</script>

{#if projectPath && sceneRoot}
  <div class="scene-browser">
    <FileTree
      rootPath={sceneRoot}
      {viewStateCache}
      {viewStateKey}
      {refreshKey}
      {selectedPath}
      revealRequest={effectiveReveal}
      onRevealComplete={handleRevealComplete}
      includeFile={(node) => node.name.toLowerCase().endsWith('.txt')}
      menu={toolbarMenu}
      onOpen={(node) => void openScene(node.path)}
      onDoubleClick={(node) => void openScene(node.path)}
      onBlankContextMenu={(dir, event) => (blankMenu = { x: event.clientX, y: event.clientY, dir })}
      onItemContextMenu={(node, event) => (itemMenu = { x: event.clientX, y: event.clientY, node })}
      dragText={(node) => (projectPath ? browserRelativePath(projectPath, node.path) : undefined)}
      onDropPaths={(dir, paths) => void handleDropPaths(dir, paths)}
      badge={rowBadge}
    />
  </div>

  {#if blankMenu}
    <ContextMenu x={blankMenu.x} y={blankMenu.y} items={blankItems} onClose={() => (blankMenu = null)} />
  {/if}

  {#if itemMenu}
    <ContextMenu x={itemMenu.x} y={itemMenu.y} items={itemItems} onClose={() => (itemMenu = null)} />
  {/if}

  {#if prompt}
    <NameInputDialog
      title={promptTitle}
      label="名称"
      initialValue={promptInitial}
      selectStem={prompt.mode === 'rename'}
      hint={prompt.mode === 'file' ? '缺扩展名时自动补 .txt' : undefined}
      validate={validateTarget}
      onClose={() => (prompt = null)}
      onSubmit={submitPrompt}
    />
  {/if}
{/if}

<!--
  `badge` 是 Snippet, 不能从普通函数里返回 —— 只能在模板层声明一个内联 snippet 来承接参数。
-->
{#snippet rowBadge(node: FileNode)}
  <!-- 值在父级算好再传进来; 每行只做 O(1) 查表 (见 `gitLetters` / `diagCounts`) -->
  {@const rel = badgeRel(node)}
  {@const counts = diagCounts.get(node.path)}
  <FileBadges
    path={node.path}
    {rel}
    letter={gitLetters.get(normalizeRelPath(rel)) ?? null}
    errors={counts?.errors ?? 0}
    warnings={counts?.warnings ?? 0}
  />
{/snippet}
